    33→def load_project_config(project_root: Path | str) -> Dict[str, Any]:
    34→    """Load project config from se3.yaml (fallback: se3.config.yaml)."""
    35→    if isinstance(project_root, str):
    36→        project_root = Path(project_root)
    37→    config_file = project_root / "se3.yaml"
