   814→    @contextmanager
   815→    def atomic_bump(
   816→        self,
   817→        bump_type: Optional[BumpType] = None,
   818→        task_type: Optional[TaskType] = None,
   819→        path: Optional[Path] = None,
   820→    ) -> Generator[str, None, None]:
